/** @type {import('./constants.mjs').MODULES} */
const MODULE_LIST = MODULES;

function moduleTitleFor(page) {
  const mod = MODULE_LIST.find((m) => m.id.startsWith('m') && page >= m.start && page <= m.end);
  return mod?.title ?? '';
}

