export function getAllTeachingSpecs() {
  return TEACHING_SPECS.map((s) => ({
    ...s,
    moduleTitle: s.moduleTitle || moduleTitleFor(s.page),
  }));
}

export function getFullTeachingSpec(page) {
  if (page < 1 || page > 138) return null;
  return getAllTeachingSpecs().find((s) => s.page === page) ?? null;
}

export function getFullVisualSpec(page) {
  if (page < 139 || page > 600) return null;
  const spec = buildVisualSpec(page);
  if (!spec) return null;
  const stream = VISUAL_STREAMS.find((s) => page >= s.start && page <= s.end);
  const mod = MODULE_LIST.find((m) => m.id === stream?.module);
  return {
    ...spec,
    moduleTitle: stream ? `${stream.brand} · ${stream.tag}` : '案例视觉流',
    moduleId: stream?.module ?? 'v-case',
    streamRange: stream ? [stream.start, stream.end] : undefined,
    linkedModule: mod?.title,
  };
}

export function getVisualStreamMdSection() {
  const lines = [
    '以下第139–600页为案例视觉流，按品牌/主题分14条流，每条30页、3个beat、每beat 10镜。',
    '',
    `| 页码 | 品牌 | 标签 | 关联模块 | Beats |`,
    `| --- | --- | --- | --- | --- |`,
  ];
  for (const s of VISUAL_STREAMS) {
    const mod = MODULE_LIST.find((m) => m.id === s.module);
    lines.push(
      `| ${s.start}–${s.end} | ${s.brand} | ${s.tag} | ${mod?.title ?? s.module} | ${s.beats.join(' / ')} |`,
    );
  }
  lines.push('', '### 使用说明', '');
  lines.push('- 视觉流页以 `flash` / `split-text` 为主，讲师少解说、多指屏对照上午模型。');
  lines.push('- 每 beat 10 镜，第1镜报幕，第10镜收束可迁移动作。');
  lines.push('- 559–600 为结营回顾与六十天契约闭环。');
  lines.push('', `> ${DECK_SUB} · ${DECK_TAGLINE}`);
  return lines.join('\n');
}

export function getPageSpec(page) {
  if (page <= 138) return getFullTeachingSpec(page);
  return getFullVisualSpec(page);
}
